// Step 1: Validate input and set defaults for kahunaworkforce.com
const input = $input.first().json;
const body = input.body || input;

const config = {
  domain: body.domain || 'kahunaworkforce.com',
  ga4_property_id: body.ga4_property_id || '',
  gsc_site_url: body.gsc_site_url || 'https://kahunaworkforce.com/',
  semrush_api_key: body.semrush_api_key || '',
  database: body.database || 'us',
  date_range_days: body.date_range_days || 90,
  top_n_pages: body.top_n_pages || 20,
  competitors: body.competitors || [],
  limit: body.limit || 100
};

if (!config.ga4_property_id) {
  return [{ json: { error: true, message: 'ga4_property_id is required. Find it in GA4 Admin > Property Settings.' } }];
}

if (!config.semrush_api_key) {
  return [{ json: { error: true, message: 'semrush_api_key is required.' } }];
}

const startDate = new Date(Date.now() - config.date_range_days * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const endDate = new Date().toISOString().split('T')[0];

return [{ json: { ...config, start_date: startDate, end_date: endDate } }];

// Merge all data sources and produce the unified SEO dataset
const config = $('Validate Input').first().json;
const ga4Raw = $('GA4: Top Pages by Traffic').first().json;
const gscRaw = $('GSC: Keywords & Pages').first().json;
const semrushOrganic = $('SEMrush: Organic Keywords').first().json;
const semrushCompetitors = $('SEMrush: Find Competitors').first().json;

// Parse GA4 results into page objects
let ga4Pages = [];
try {
  const rows = ga4Raw.rows || [];
  ga4Pages = rows.map(row => ({
    page_path: row.dimensionValues[0].value,
    page_title: row.dimensionValues[1].value,
    pageviews: parseInt(row.metricValues[0].value || 0),
    sessions: parseInt(row.metricValues[1].value || 0),
    conversions: parseInt(row.metricValues[2].value || 0),
    users: parseInt(row.metricValues[3].value || 0),
    bounce_rate: parseFloat(row.metricValues[4].value || 0),
    avg_session_duration: parseFloat(row.metricValues[5].value || 0),
    engagement_rate: parseFloat(row.metricValues[6].value || 0)
  }));
  // Calculate traffic x conversion score and sort
  ga4Pages = ga4Pages.map(p => ({
    ...p,
    traffic_x_conversion: p.sessions * (p.conversions / Math.max(p.sessions, 1)),
    conversion_rate: p.sessions > 0 ? (p.conversions / p.sessions * 100).toFixed(2) : '0.00'
  }));
  ga4Pages.sort((a, b) => b.traffic_x_conversion - a.traffic_x_conversion);
  ga4Pages = ga4Pages.slice(0, config.top_n_pages);
} catch (e) {
  ga4Pages = [{ error: 'Failed to parse GA4 data', details: e.message }];
}

// Parse GSC keywords
let gscKeywords = [];
try {
  const rows = gscRaw.rows || [];
  gscKeywords = rows.map(row => ({
    keyword: row.keys[0],
    page: row.keys[1],
    clicks: row.clicks,
    impressions: row.impressions,
    ctr: (row.ctr * 100).toFixed(2),
    position: row.position.toFixed(1)
  }));
} catch (e) {
  gscKeywords = [{ error: 'Failed to parse GSC data', details: e.message }];
}

// Parse SEMrush organic keywords (CSV format)
let semrushKeywords = [];
try {
  if (typeof semrushOrganic === 'string' || semrushOrganic.data) {
    const csvText = typeof semrushOrganic === 'string' ? semrushOrganic : semrushOrganic.data;
    const lines = csvText.split('\n').filter(l => l.trim());
    if (lines.length > 1) {
      const headers = lines[0].split(';');
      semrushKeywords = lines.slice(1).map(line => {
        const vals = line.split(';');
        return {
          keyword: vals[0],
          position: parseInt(vals[1]),
          search_volume: parseInt(vals[2]),
          cpc: parseFloat(vals[3]),
          competition: parseFloat(vals[4]),
          keyword_difficulty: parseInt(vals[5]),
          url: vals[6],
          traffic: parseFloat(vals[7]),
          traffic_cost: parseFloat(vals[8]),
          search_intent: vals[9] || 'unknown'
        };
      });
    }
  }
} catch (e) {
  semrushKeywords = [{ error: 'Failed to parse SEMrush organic data', details: e.message }];
}

// Parse SEMrush competitors
let competitors = [];
try {
  if (typeof semrushCompetitors === 'string' || semrushCompetitors.data) {
    const csvText = typeof semrushCompetitors === 'string' ? semrushCompetitors : semrushCompetitors.data;
    const lines = csvText.split('\n').filter(l => l.trim());
    if (lines.length > 1) {
      competitors = lines.slice(1).map(line => {
        const vals = line.split(';');
        return {
          domain: vals[0],
          common_keywords: parseInt(vals[1]),
          se_keywords: parseInt(vals[2]),
          organic_traffic: parseInt(vals[3]),
          organic_cost: parseFloat(vals[4]),
          paid_keywords: parseInt(vals[5]),
          paid_traffic: parseInt(vals[6])
        };
      });
    }
  }
} catch (e) {
  competitors = [{ error: 'Failed to parse competitors data', details: e.message }];
}

// Auto-classify keywords by intent
const classifyIntent = (kw) => {
  const keyword = (kw.keyword || '').toLowerCase();
  const intent = (kw.search_intent || '').toLowerCase();
  // Use SEMrush intent if available
  if (intent && intent !== 'unknown') {
    const intentMap = { '0': 'informational', '1': 'navigational', '2': 'commercial', '3': 'transactional' };
    return intentMap[intent] || intent;
  }
  // Fallback heuristic classification
  if (/buy|price|cost|cheap|deal|discount|order|purchase|hire|get/.test(keyword)) return 'transactional';
  if (/best|top|review|compare|vs|alternative/.test(keyword)) return 'commercial';
  if (/how|what|why|when|guide|tutorial|tips|learn/.test(keyword)) return 'informational';
  return 'navigational';
};

const classifiedKeywords = semrushKeywords.map(kw => ({
  ...kw,
  intent_category: classifyIntent(kw)
}));

// Build the unified output
return [{
  json: {
    pipeline_step: 'data_collection',
    domain: config.domain,
    generated_at: new Date().toISOString(),
    summary: {
      ga4_top_pages_count: ga4Pages.length,
      gsc_keywords_count: gscKeywords.length,
      semrush_keywords_count: classifiedKeywords.length,
      competitors_found: competitors.length,
      intent_breakdown: {
        transactional: classifiedKeywords.filter(k => k.intent_category === 'transactional').length,
        commercial: classifiedKeywords.filter(k => k.intent_category === 'commercial').length,
        informational: classifiedKeywords.filter(k => k.intent_category === 'informational').length,
        navigational: classifiedKeywords.filter(k => k.intent_category === 'navigational').length
      }
    },
    ga4_top_pages: ga4Pages,
    gsc_keywords: gscKeywords,
    semrush_keywords: classifiedKeywords,
    competitors: competitors,
    next_steps: [
      'Run keyword gap analysis against top competitors',
      'Cross-reference GA4 top pages with SEMrush keyword data',
      'Identify pages with high traffic but low conversion for optimization',
      'Feed data to content optimizer workflow'
    ]
  }
}];

// Parse keyword gap data and enrich the collection output
const collection = $('Merge & Classify Data').first().json;
const gapRaw = $('SEMrush: Keyword Gap').first().json;
const config = $('Validate Input').first().json;

let keywordGaps = [];
try {
  if (typeof gapRaw === 'string' || gapRaw.data) {
    const csvText = typeof gapRaw === 'string' ? gapRaw : gapRaw.data;
    const lines = csvText.split('\n').filter(l => l.trim());
    if (lines.length > 1) {
      keywordGaps = lines.slice(1).map(line => {
        const vals = line.split(';');
        return {
          keyword: vals[0],
          your_position: vals[1] === '' ? 'not_ranking' : parseInt(vals[1]),
          competitor_positions: vals.slice(2, 6).map(v => v === '' ? 'not_ranking' : parseInt(v)),
          search_volume: parseInt(vals[6] || 0),
          keyword_difficulty: parseInt(vals[7] || 0),
          intent: vals[8] || 'unknown'
        };
      });
      // Focus on keywords where we're NOT ranking but competitors ARE
      keywordGaps = keywordGaps.filter(k => k.your_position === 'not_ranking');
      keywordGaps.sort((a, b) => b.search_volume - a.search_volume);
    }
  }
} catch (e) {
  keywordGaps = [{ error: 'Failed to parse keyword gap data', details: e.message }];
}

return [{
  json: {
    ...collection,
    keyword_gap_analysis: {
      total_gap_keywords: keywordGaps.length,
      top_opportunities: keywordGaps.slice(0, 50),
      by_intent: {
        transactional: keywordGaps.filter(k => /transactional|3/.test(k.intent)).length,
        commercial: keywordGaps.filter(k => /commercial|2/.test(k.intent)).length,
        informational: keywordGaps.filter(k => /informational|0/.test(k.intent)).length
      }
    }
  }
}];
